function BoosterStore(){const {gems,addGems,notify,vibration}=useGame();const inventory=useBoosterInventory(state=>state.inventory);const offers=[['freeze','FREEZE','Stops enemies for 2 seconds',10],['army','+7 BOTS','Adds seven robots to your army',15],['blast','BLAST','Damages every enemy for 2 seconds',20]] as const;const buy=(type:'freeze'|'army'|'blast',cost:number)=>{if(gems<cost){notify(`Need ${cost-gems} more gems`);VibrationService.error(vibration);return}addGems(-cost);useBoosterInventory.getState().grant(type);VibrationService.success(vibration);notify(`${type==='army'?'+7 BOTS':type.toUpperCase()} added to inventory`);AnalyticsService.track('booster_purchased',{type,cost})};return <div className="booster-store">{offers.map(([type,name,description,cost])=><article className={`booster-shop-card booster-shop-${type}`} key={type}><div className={`booster-shop-icon booster-art-${type}`} style={{backgroundImage:`url(${boosterRewardsArt})`}} aria-hidden="true"/><div><b>{name}</b><small>{description}</small><em>IN INVENTORY: {inventory[type]}</em></div><button onClick={()=>buy(type,cost)}><CurrencyIcon kind="gem" size={18}/>{cost}</button></article>)}</div>}

