const translate=(language:Language,value:string)=>language==='ru'?RU_TEXT[value]||value:value;
const translateRuntimeText=(language:Language,value:string)=>{
  if(language!=='ru'||!value.trim())return value;
  const leading=value.match(/^\s*/)?.[0]||'',trailing=value.match(/\s*$/)?.[0]||'',body=value.slice(leading.length,value.length-trailing.length||undefined);
  let next=RU_TEXT[body]||body;
  if(next===body){
    const patterns:[RegExp,string][]=[
      [/^Battle Pass · Lv\. (\d+) Premium$/,'Боевой пропуск · премиум, ур. $1'],[/^Battle Pass · Lv\. (\d+)$/,'Боевой пропуск · ур. $1'],[/^Level (\d+) \/ (\d+)$/,'Уровень $1 / $2'],[/^Level (\d+)$/,'Уровень $1'],[/^World (\d+) · Levels (\d+)[–-](\d+)$/,'Мир $1 · уровни $2–$3'],[/^Play Level (\d+)$/,'Играть · уровень $1'],[/^Preparing your squad for Level (\d+)$/,'Подготовка отряда к уровню $1'],[/^Unlocks? at Level (\d+)$/,'Открывается на уровне $1'],[/^Reach Level (\d+)$/,'Достигните уровня $1'],[/^Day (\d+)$/,'День $1'],[/^(\d+) COINS$/,'$1 КОИНОВ'],[/^(\d+) GEMS$/,'$1 ГЕМОВ']
    ];
    for(const [pattern,replacement] of patterns){if(pattern.test(body)){next=body.replace(pattern,replacement);break}}
  }
  if(next===body)next=next.replace(/\bLevel\b/g,'Уровень').replace(/\bLevels\b/g,'Уровни').replace(/\bWorld\b/g,'Мир').replace(/\bDaily\b/g,'Дневные').replace(/\bWeekly\b/g,'Недельные').replace(/\bCOINS\b/g,'КОИНОВ').replace(/\bGEMS\b/g,'ГЕМОВ').replace(/\bCLAIMED\b/g,'ПОЛУЧЕНО').replace(/\bLOCKED\b/g,'ЗАБЛОКИРОВАНО').replace(/\bBUY\b/g,'КУПИТЬ').replace(/\bUNLOCK\b/g,'ОТКРЫТЬ').replace(/\bPREMIUM\b/g,'ПРЕМИУМ').replace(/\bEQUIP\b/g,'НАДЕТЬ').replace(/\bDMG\b/g,'УРОН').replace(/\bHP\b/g,'ЗДОР.').replace(/\bSPD\b/g,'СКОР.').replace(/\bARMOR\b/g,'БРОНЯ').replace(/\bRATE\b/g,'СКОРОСТЬ').replace(/\bNeed\b/g,'Нужно').replace(/\bmore\b/g,'ещё').replace(/\bcoins\b/g,'коинов').replace(/\bgems\b/g,'гемов').replace(/\bbattles\b/g,'боёв').replace(/\bbattle\b/g,'бой').replace(/\bskin\b/g,'скин').replace(/\breward\b/g,'награда').replace(/\brewards\b/g,'награды').replace(/\bdamage\b/g,'урон').replace(/\bhealth\b/g,'здоровье').replace(/\bsize\b/g,'размер');
  return leading+next+trailing;
};
const translatedTextRecords=new WeakMap<Text,{original:string;last:string}>();
const translatedAttributeRecords=new WeakMap<Element,Record<string,{original:string;last:string}>>();
const applyLanguageToDom=(language:Language)=>{
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  let node=walker.nextNode() as Text|null;
  while(node){const parent=node.parentElement;if(parent&&!parent.closest('script,style,textarea,input,[contenteditable="true"]')){const current=node.nodeValue||'';let record=translatedTextRecords.get(node);if(!record||current!==record.last){record={original:current,last:current};translatedTextRecords.set(node,record)}const next=translateRuntimeText(language,record.original);if(current!==next)node.nodeValue=next;record.last=next}node=walker.nextNode() as Text|null}
  document.body.querySelectorAll<HTMLElement>('[aria-label],[title],[placeholder]').forEach(element=>{const records=translatedAttributeRecords.get(element)||{};for(const name of ['aria-label','title','placeholder']){const current=element.getAttribute(name);if(current===null)continue;let record=records[name];if(!record||current!==record.last){record={original:current,last:current};records[name]=record}const next=translateRuntimeText(language,record.original);if(current!==next)element.setAttribute(name,next);record.last=next}translatedAttributeRecords.set(element,records)})
};
