// Native lifecycle is explicit so Android cannot keep a WebView audio watchdog alive
// after the game is backgrounded, while returning to the app restores the right track.
const resumeCurrentAudio=()=>{const state=useGame.getState();if(!state.music)return;if(state.screen==='battle'){AudioManager.play(selectedBattleLevel(state.level)%10===0?'boss_theme':'battle_theme','music');return}if(state.screen!=='result'&&state.screen!=='defeat')AudioManager.play('lobby_theme','music')};
if(Capacitor.isNativePlatform())void CapacitorApp.addListener('appStateChange',({isActive})=>{if(isActive)resumeCurrentAudio();else{AudioManager.stop('music');AudioManager.stop('sfx')}});
if(Capacitor.isNativePlatform()){
  window.addEventListener('mobo-war-native-pause',()=>{AudioManager.stop('music');AudioManager.stop('sfx')});
  window.addEventListener('mobo-war-native-resume',resumeCurrentAudio);
}

// One durable record commits outcome, currency and campaign advancement together.
// Android's hardware Back is a pause action while the battle is active. Keep
// the existing global navigation handler for every other screen.
const nativeAddListener=(CapacitorApp as any).addListener.bind(CapacitorApp);
