let journal=readJournal(useGame.getState());
useGame.setState(journal.progress);
let lastReceipt:BattleReceipt|null=null;
let pendingDefeatCheckpoint:BattleCheckpoint|null=null;
let activeReviveCheckpoint:BattleCheckpoint|null=null;
const persistJournal=()=>{try{localStorage.setItem(PROGRESS_KEY,JSON.stringify(journal))}catch{useGame.setState({toast:'Storage unavailable. Keep this tab open to retain progress.'})}};
useGame.subscribe((state,previous)=>{if(state.coins!==previous.coins||state.gems!==previous.gems||state.level!==previous.level||state.wins!==previous.wins){journal={...journal,progress:{coins:state.coins,gems:state.gems,level:state.level,wins:state.wins}};persistJournal()}});
let languageObserver:MutationObserver|undefined;
const startLanguageObserver=()=>{if(languageObserver||!document.body)return;let running=false;const sync=()=>{if(running)return;running=true;applyLanguageToDom(useGame.getState().language);running=false};sync();languageObserver=new MutationObserver(sync);languageObserver.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','placeholder']});window.addEventListener('mobo-language-changed',sync)};
