function saveBattleProgress(){persistJournal();useGame.setState(journal.progress)}
function completeBattle(outcome:BattleOutcome,checkpoint?:BattleCheckpoint){
  const before=useGame.getState(),world=getWorldByLevel(outcome.level),analyticsInput={battleId:outcome.id,level:outcome.level,world:world.key,playerLevel:before.level,selectedUnit:`unit_${before.equippedUnit}`,selectedWeapon:`weapon_${before.equippedWeapon}`,unitLevel:before.unitLevels[before.equippedUnit]||1,weaponLevel:before.weaponLevels[before.equippedWeapon]||1,challenge:Boolean(outcome.challenge),durationSeconds:outcome.seconds};
  pendingDefeatCheckpoint=outcome.result==='defeat'?checkpoint||null:null;
  journal=settle(journal,outcome);lastReceipt=journal.receipts.find(r=>r.id===outcome.id)!;
  if(outcome.result==='victory')AnalyticsService.trackLevelComplete({...analyticsInput,coinsEarned:lastReceipt.coins+(lastReceipt.chapterReward?.coins||0),gemsEarned:lastReceipt.gems+(lastReceipt.chapterReward?.gems||0)});
  else AnalyticsService.trackLevelFailed({...analyticsInput,failureReason:'battle_lost'});
  saveBattleProgress();
  const after=useGame.getState();
  AnalyticsService.updatePlayerProperties({playerLevel:after.level,currentWorld:getWorldByLevel(after.level).key,highestLevelReached:after.level,payerStatus:localStorage.getItem('starterPackPurchased')==='true'?'payer':'non_payer'});
  useGame.getState().setScreen(outcome.result==='victory'?'result':'defeat')
}

