function Lobby(){const {setScreen,level,wins,weaponLevels,coins}=useGame();const starterOffer=useStarterOffer();const {claimedFree,claimedPremium,premiumUnlocked}=useBattlePass();const today=TimeService.dayKey();const world=getWorldByLevel(level);const missionClaimed=safeArray('mobo-mission-claimed');const missionReady=[wins>=5,weaponLevels.some(itemLevel=>itemLevel>1),wins>=3,coins>=1000];const missionReadySignature=`${today}:${missionReady.map(ready=>ready?'1':'0').join('')}`;const passLevel=Math.min(50,Math.floor(passXpFor(wins)/20)),passReady=Array.from({length:passLevel},(_,index)=>index+1).some(tier=>!claimedFree.includes(tier)||(premiumUnlocked&&!claimedPremium.includes(tier))),passNotice=passReady||localStorage.getItem('mobo-notice-events-seen')!=='true';const missionNotice=localStorage.getItem('mobo-notice-missions-seen')!=='true'||localStorage.getItem('mobo-notice-missions-ready')!==missionReadySignature||missionReady.some((ready,index)=>ready&&!missionClaimed.includes(index)&&localStorage.getItem(`mobo-notice-mission-${index}`)!=='true');const dailyNotice=localStorage.getItem(`mobo-notice-daily-${today}`)!=='true';const crystalNotice=localStorage.getItem('mobo-notice-crystal-seen')!=='true';const open=(target:Screen,key:string)=>{localStorage.setItem(key,'true');setScreen(target)};const openMissions=()=>{missionReady.forEach((ready,index)=>{if(ready)localStorage.setItem(`mobo-notice-mission-${index}`,'true')});localStorage.setItem('mobo-notice-missions-seen','true');localStorage.setItem('mobo-notice-missions-ready',missionReadySignature);setScreen('missions')};const openCrystal=()=>open('crystal','mobo-notice-crystal-seen');const play=()=>{sessionStorage.removeItem('mobo-selected-level');setScreen(localStorage.getItem('mobo-tutorial-seen')==='true'?'map':'tutorial')};return <><LobbyTopBar/><section className={`lobby-screen lobby-world-${world.key}`} style={{'--lobby-background':`url(${lobbyBackgroundFor(world.key)})`} as React.CSSProperties}><div className="lobby-world-layer" aria-hidden="true"/><div className="lobby-quick-actions lobby-quick-left"><button className="lobby-quick-action" onClick={openMissions}><span><LobbyQuickIcon kind="missions"/></span><small>MISSIONS</small>{missionNotice&&<i className="notice-dot" aria-hidden="true"/>}</button><button className="lobby-quick-action" onClick={()=>open('daily',`mobo-notice-daily-${today}`)}><span><LobbyQuickIcon kind="daily"/></span><small>DAILY<br/>REWARDS</small>{dailyNotice&&<i className="notice-dot" aria-hidden="true"/>}</button></div><div className="lobby-quick-actions lobby-quick-right"><button className="lobby-quick-action" onClick={openCrystal}><span><LobbyQuickIcon kind="crystal"/></span><small>CRYSTAL<br/>CHALLENGE</small>{crystalNotice&&<i className="notice-dot" aria-hidden="true"/>}</button>{starterOffer.isActive&&<button className="lobby-quick-action lobby-starter-offer" onClick={openStarterOffer}><span><img src={unitSkinArt(2,'blackgold')} alt=""/></span><small>24H OFFER</small><em>50K COINS</em><b>-80%</b></button>}</div><div className="lobby-center"><Button onClick={play}><span>PLAY</span></Button></div><LobbyBottomNav/></section></>}
function MenuTopBar(){const {coins,gems,level,setScreen,language}=useGame();const [playerName,setPlayerName]=useState(readPlayerName);useEffect(()=>{const update=()=>setPlayerName(readPlayerName());window.addEventListener('mobo-player-name-changed',update);return()=>window.removeEventListener('mobo-player-name-changed',update)},[]);const openShop=()=>{markShopNoticeSeen();setScreen('shop')};return <div className="topbar menu-topbar"><button type="button" className="player menu-player" onClick={()=>setScreen('profile')} aria-label={`Open player profile for ${playerName}`}><span className="avatar"><img src={lobbyCommanderAvatar} alt=""/></span><div><b>{playerName}</b><small>{translate(language,'Level')} {level}</small></div></button><div className="currency"><button type="button" className="legacy-currency-pill" onClick={openShop} aria-label="Open shop for coins"><img className="currency-art" src={currencyCoinArt} alt=""/><b>{formatHudAmount(coins)}</b><i>+</i></button><button type="button" className="legacy-currency-pill" onClick={openShop} aria-label="Open shop for gems"><img className="currency-art" src={currencyGemArt} alt=""/><b>{formatHudAmount(gems)}</b><i>+</i></button><button className="icon" onClick={()=>setScreen('settings')} aria-label="Settings">⚙</button></div></div>}
function Header({title}:{title:string}){const language=useGame(state=>state.language);return <><MenuTopBar/><div className="pagehead"><button className="back" onClick={goToLobby}>‹</button><h2>{translate(language,title)}</h2></div></>}
const missionWeekKey=()=>{const now=TimeService.now(),weekStart=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate())),daysFromMonday=(weekStart.getUTCDay()+6)%7;weekStart.setUTCDate(weekStart.getUTCDate()-daysFromMonday);return weekStart.toISOString().slice(0,10)};
const missionCounter=(key:string,fallback:number)=>{const saved=localStorage.getItem(key),value=saved===null?fallback:Number(saved);if(saved===null||!Number.isFinite(value)){localStorage.setItem(key,String(fallback));return fallback}return value};
const missionUpgradeTotal=(state:Pick<GameState,'unitLevels'|'weaponLevels'>)=>state.unitLevels.reduce((sum,itemLevel)=>sum+Math.max(0,itemLevel-1),0)+state.weaponLevels.reduce((sum,itemLevel)=>sum+Math.max(0,itemLevel-1),0);
const ensureMissionPeriods=()=>{const state=useGame.getState(),day=TimeService.dayKey(),week=missionWeekKey(),upgrades=missionUpgradeTotal(state),bosses=journal.receipts.filter(receipt=>receipt.result==='victory'&&!receipt.challenge&&receipt.level%10===0).length;missionCounter(`mobo-mission-daily-wins-${day}`,state.wins);missionCounter(`mobo-mission-daily-upgrades-${day}`,upgrades);missionCounter(`mobo-mission-daily-bosses-${day}`,bosses);missionCounter(`mobo-mission-weekly-wins-${week}`,state.wins);missionCounter(`mobo-mission-weekly-upgrades-${week}`,upgrades);missionCounter(`mobo-mission-weekly-bosses-${week}`,bosses)};
ensureMissionPeriods();
function MapTopBar(){const {coins,gems,level,setScreen}=useGame();const openShop=()=>{markShopNoticeSeen();setScreen('shop')};const xp=Math.min(100,(level%10||10)*10);return <div className="map-topbar"><button type="button" className="map-back" onClick={goToLobby} aria-label="Back to lobby">‹</button><button type="button" className="map-level-profile" onClick={()=>setScreen('profile')} aria-label="Open player profile"><span><img src={lobbyCommanderAvatar} alt=""/></span><div><b>Level {level}</b><i><em style={{width:`${xp}%`}}/></i></div></button><div className="map-currencies"><span><img className="currency-art" src={currencyCoinArt} alt=""/><b>{formatHudAmount(coins)}</b><button type="button" onClick={openShop} aria-label="Open shop for coins">+</button></span><span><img className="currency-art" src={currencyGemArt} alt=""/><b>{formatHudAmount(gems)}</b><button type="button" onClick={openShop} aria-label="Open shop for gems">+</button></span><button className="icon" onClick={()=>setScreen('settings')} aria-label="Settings">⚙</button></div></div>}
function MapScreen(){
  const {setScreen,level}=useGame();
  const [selected,setSelected]=useState(()=>selectedBattleLevel(level));
  const [worldId,setWorldId]=useState(()=>getWorldByLevel(selectedBattleLevel(level)).id);
  const world=getWorldById(worldId);
  const mapAsset=world.key==='green'?greenReferenceMap:world.key==='ice'?iceReferenceMap:world.key==='dark'?mapDark:world.key==='wasteland'?mapWasteland:world.key==='lava'?mapLava:mapBg;
  const mapAspect=world.key==='ice'?'1017 / 1546':'2 / 3';
  const nodes=getWorldMapNodes(world,level);
  const choose=(nextLevel:number)=>{if(!nextLevel||nextLevel>level)return;setSelected(nextLevel);sessionStorage.setItem('mobo-selected-level',String(nextLevel))};
  const openWorld=(targetId:number)=>{const target=getWorldById(targetId);if(target.levelStart>level)return;setWorldId(target.id);const nextSelected=Math.min(level,target.levelEnd),nextLevel=Math.max(target.levelStart,nextSelected);choose(nextLevel);AnalyticsService.trackWorldSelected(target.key,nextLevel)};
  const play=()=>{AnalyticsService.trackPlayClicked(selected,world.key);sessionStorage.setItem('mobo-selected-level',String(selected));setScreen('loadout')};
   return <>
      <MenuTopBar/>
    <div className={`map world-map-${world.key}`} style={{'--map-aspect':mapAspect,'--map-backdrop':world.mapTheme.gradient} as React.CSSProperties}>
      <div className="map-viewport">
        <div className="map-canvas" style={{backgroundImage:`url('${mapAsset}')`,borderColor:world.mapTheme.accent}}>
      <div className="chapter"><b>{world.name}</b><small>World {world.id} · Levels {world.levelStart}–{world.levelEnd}</small></div>
      <div className="map-level-scroll" aria-label={`${world.name} level map`}>
        <div className="path">
          <div className="route-track"/>
          {nodes.map(node=>{const transition=node.type==='nextWorldNode'||node.type==='previousWorldNode',targetWorld=node.targetWorldId?getWorldById(node.targetWorldId):null;const unlocked=transition?!!targetWorld&&targetWorld.levelStart<=level:!!node.level&&node.level<=level;return <button key={node.id} disabled={!unlocked} aria-label={node.label} data-completed={!transition && !!node.level && node.level<level} data-unlocked={transition?unlocked:undefined} className={`map-node ${node.type} ${targetWorld?`transition-to-${targetWorld.key}`:''} ${transition?(unlocked?'world-transition-open':'world-transition-locked'):''} ${selected===node.level?'selected-node':''}`} style={{left:`${node.x}%`,top:`${node.y}%`}} onClick={()=>transition?openWorld(node.targetWorldId!):choose(node.level!)}>{transition?<><svg className="island-art" viewBox="0 0 160 140" aria-hidden="true"><path fill="#314f76" d="M12 77L28 108 57 114 76 139 96 112 131 106 150 77Z"/><path fill="#658cae" d="M12 77L57 114 49 81ZM76 139L96 112 101 79ZM131 106L150 77 120 78Z"/><ellipse cx="80" cy="76" rx="70" ry="23" fill="var(--island-ground,#dafaff)"/><path fill="var(--island-mountain,#83c9eb)" d="M25 72L47 20 71 69 91 8 127 74Z"/><path fill="#f5ffff" d="M35 49L47 20 59 48 47 41ZM77 39L91 8 109 40 94 31Z"/><path fill="#96d9f5" stroke="#e6fcff" strokeWidth="2" d="M58 74V46H70V32H85V46H100V74Z"/><path fill="#2370a5" d="M69 32L77 17 86 32ZM57 46L64 34 71 46ZM85 46L94 33 101 46Z"/><path fill="#284668" d="M72 75V61Q79 49 86 61V75Z"/></svg><span className="world-island-copy"><b>{node.type==='nextWorldNode'?'Next World':'Previous World'}</b><strong>{targetWorld?.name}</strong><small>{unlocked?'Tap to travel':'Coming Soon!'}</small></span>{!unlocked&&<i className="world-island-lock">🔒</i>}</>:<><span className="level-number">{node.icon}</span>{node.type==='elite'&&<span className="node-badge">♛</span>}{node.type==='boss'&&<span className="node-badge">☠</span>}{!unlocked&&<span className="node-lock">🔒</span>}</>}</button>})}
        </div>
      </div>
        </div>
      </div>
    </div>
    <Button onClick={play} style={{'--play-glow':world.mapTheme.accent,'--play-glow-soft':`${world.mapTheme.accent}88`} as React.CSSProperties}><span>PLAY LEVEL {selected}</span><b aria-hidden="true">›</b></Button>
  </>
 }
function Loadout(){
  const {setScreen,level,equippedUnit,equippedWeapon,unitLevels,weaponLevels,ownedUnits,ownedWeapons,unitSkins,equip,purchase,vibration,notify}=useGame();
  const inventory=useBoosterInventory(state=>state.inventory);
  const [activeTab,setActiveTab]=useState<'units'|'weapons'|'boosters'>('units');
  const battleLevel=selectedBattleLevel(level),world=getWorldByLevel(battleLevel),unit=units[equippedUnit]||units[0],weapon=weapons[equippedWeapon]||weapons[0];
  const unlockLevels=[1,11,21];
  const previewFor=(unitIndex:number,weaponIndex:number)=>battleConfig({level:battleLevel,unitIndex,weaponIndex,unitLevel:unitLevels[unitIndex]||1,weaponLevel:weaponLevels[weaponIndex]||1,skin:unitSkins[unitIndex]||'default'});
  const activePreview=previewFor(equippedUnit,equippedWeapon);
  const select=(kind:'unit'|'weapon',index:number)=>{
    const required=unlockLevels[index],owned=kind==='unit'?ownedUnits[index]:ownedWeapons[index],type=kind==='unit'?'unit':'weapon';
    if(level<required){notify(`Unlocks at Level ${required}`);VibrationService.error(vibration);return}
    if(!owned){if(!purchase(type,index)){VibrationService.error(vibration);return}VibrationService.success(vibration)}
    equip(type,index);VibrationService.tap(vibration);AnalyticsService.track('loadout_selection_changed',{type,index});
  };
  const optionClass=(selected:boolean,locked:boolean)=>`loadout-option ${selected?'selected-loadout-option ':''}${locked?'locked-loadout-option':''}`;
  return <>
    <Header title={`Level ${battleLevel}`}/>
    <div className="loadout-deck">
      <div className="loadout-kicker">COMMAND DECK · WORLD {world.id}</div>
      <div className="loadout-title-row"><div><small>MISSION READY</small><h1>PREPARE FOR BATTLE</h1></div><strong>LV. {battleLevel}</strong></div>
      <div className="loadout-stage">
        <div className="loadout-equipped-strip"><div><img src={unitSkinArt(equippedUnit,unitSkins[equippedUnit]||'default')} alt=""/><span><small>ACTIVE UNIT</small><b>{unit[0]}</b></span></div><i/><div><img src={weaponArt[equippedWeapon]||weaponArt[0]} alt=""/><span><small>ACTIVE WEAPON</small><b>{weapon[0]}</b></span></div></div>
        <div className="loadout-stage-ring"/>
        <img className="loadout-stage-unit" src={unitSkinArt(equippedUnit,unitSkins[equippedUnit]||'default')} alt={unit[0]}/>
        <img className="loadout-stage-weapon" src={weaponArt[equippedWeapon]||weaponArt[0]} alt={weapon[0]}/>
      </div>
      <div className="loadout-powerline"><span><b>{Math.round(activePreview.unit.damage)}</b><small>UNIT DMG</small></span><i/><span><b>{Math.round(activePreview.unit.hp)}</b><small>UNIT HP</small></span><i/><span><b>{Math.round(activePreview.shotDamage)}</b><small>WEAPON DMG</small></span></div>
      <div className="loadout-tabs" role="tablist"><button className={activeTab==='units'?'active':''} onClick={()=>setActiveTab('units')}>YOUR UNIT</button><button className={activeTab==='weapons'?'active':''} onClick={()=>setActiveTab('weapons')}>WEAPON</button><button className={activeTab==='boosters'?'active':''} onClick={()=>setActiveTab('boosters')}>BOOSTERS</button></div>
      {activeTab==='units'&&<div className="loadout-option-grid">{units.map((item,index)=>{const selected=index===equippedUnit,owned=ownedUnits[index],locked=level<unlockLevels[index],preview=previewFor(index,equippedWeapon);return <button key={item[0]} className={optionClass(selected,locked)} disabled={locked} onClick={()=>select('unit',index)}><span className="loadout-option-art"><img src={unitSkinArt(index,unitSkins[index]||'default')} alt=""/></span><span className="loadout-option-copy"><b>{item[0]}</b><small>LV. {unitLevels[index]||1} · HP {Math.round(preview.unit.hp)} · DMG {Math.round(preview.unit.damage)}</small></span><em>{locked?`LV. ${unlockLevels[index]}`:selected?'SELECTED':owned?'EQUIP':'BUY'}</em></button>})}</div>}
      {activeTab==='weapons'&&<div className="loadout-option-grid">{weapons.map((item,index)=>{const selected=index===equippedWeapon,owned=ownedWeapons[index],locked=level<unlockLevels[index],preview=previewFor(equippedUnit,index);return <button key={item[0]} className={optionClass(selected,locked)} disabled={locked} onClick={()=>select('weapon',index)}><span className="loadout-option-art weapon-option-art"><img src={weaponArt[index]} alt=""/></span><span className="loadout-option-copy"><b>{item[0]}</b><small>LV. {weaponLevels[index]||1} · DMG {Math.round(preview.shotDamage)} · RATE {item[3]}</small></span><em>{locked?`LV. ${unlockLevels[index]}`:selected?'SELECTED':owned?'EQUIP':'BUY'}</em></button>})}</div>}
      {activeTab==='boosters'&&<div className="loadout-booster-grid">{(['freeze','army','blast'] as const).map(type=><article className={`loadout-booster-card loadout-booster-${type}`} key={type}><div className={`loadout-booster-art booster-art-${type}`} style={{backgroundImage:`url(${boosterRewardsArt})`}}/><div><b>{type==='army'?'+7 BOTS':type.toUpperCase()}</b><small>{type==='freeze'?'Stops enemies for 2 seconds':type==='army'?'Adds seven robots to your army':'Damages every enemy on the field'}</small></div><strong>{inventory[type]}</strong></article>)}</div>}
    </div>
    <Button onClick={()=>setScreen('battle')}><span>START BATTLE</span><small>LEVEL {battleLevel}</small></Button>
  </>
}
function Tutorial(){const {setScreen}=useGame();const [step,setStep]=useState(0);const cards=[['GUIDE YOUR ARMY','Swipe left or right to choose where new robots appear.','↔️'],['GROW YOUR ARMY','Pass through blue multiplier gates to create more robots.','✖️'],['DESTROY THE BASE','Your robots attack while the turret automatically aims and fires.','🤖']];const [title,text,icon]=cards[step];const finish=()=>{localStorage.setItem('mobo-tutorial-seen','true');AnalyticsService.track('tutorial_completed');setScreen('map')};return <div className="tutorial-screen"><button className="tutorial-skip" onClick={finish}>SKIP</button><div className="tutorial-icon">{icon}</div><strong>COMMANDER TRAINING</strong><h1>{title}</h1><p>{text}</p><div className="tutorial-dots">{cards.map((_,index)=><i className={index===step?'active':''} key={index}/>)}</div><Button onClick={()=>step===cards.length-1?finish():setStep(step+1)}>{step===cards.length-1?'LET’S GO':'NEXT'}</Button></div>}
function Loading(){const {setScreen,level,equippedUnit,equippedWeapon,unitSkins}=useGame();const battleLevel=selectedBattleLevel(level),world=getWorldByLevel(battleLevel);useEffect(()=>{let cancelled=false;const started=Date.now(),urls=getBattleAssetUrls(world.key,equippedUnit,equippedWeapon,unitSkins[equippedUnit]||'default');const decode=(src:string)=>new Promise<void>(resolve=>{const image=new Image();const complete=()=>{void image.decode?.().catch(()=>{}).then(()=>resolve())};image.onload=complete;image.onerror=()=>resolve();image.src=src;if(image.complete)complete()});void Promise.all(urls.map(decode)).then(()=>{const delay=Math.max(0,6400-(Date.now()-started));if(!cancelled)window.setTimeout(()=>!cancelled&&setScreen('battle'),delay)});return()=>{cancelled=true}},[setScreen,equippedUnit,equippedWeapon,unitSkins,world.key]);return <div className={`loading-screen loading-world-${world.key}`}><div className="loading-vignette" aria-hidden="true"/><main className="loading-content"><span className="loading-kicker">MISSION DEPLOYMENT</span><div className="loading-art"><img src={unitSkinArt(equippedUnit,unitSkins[equippedUnit]||'default')} alt=""/></div><h1>{world.name}</h1><p className="loading-status">Preparing your squad for Level {battleLevel}</p><div className="loading-progress" aria-label="Preparing battlefield"><i/></div><b className="loading-label">DEPLOYING BATTLEFIELD</b></main><aside className="tutorial-card"><strong>COMMANDER TIP</strong><span>Your cannon fires automatically</span><small>Swipe left or right to guide your army into position.</small></aside></div>}

const goToLobby=()=>{window.history.replaceState({moboWar:true,screen:'lobby',appDepth:0},'',window.location.href);useGame.getState().setScreen('lobby',true)};
function Result(){const challenge=!!lastReceipt?.challenge;return <BattleResult receipt={lastReceipt} onHome={()=>challenge?useGame.getState().setScreen('crystal'):goToLobby()} onNext={()=>{const state=useGame.getState(),next=lastReceipt?.result==='victory'?Math.min(state.level,lastReceipt.level+1):state.level;sessionStorage.setItem('mobo-selected-level',String(Math.max(1,next)));state.setScreen('map')}} onDouble={()=>{if(!lastReceipt)return;journal=doubleCoins(journal,lastReceipt.id);saveBattleProgress();lastReceipt=journal.receipts.find(r=>r.id===lastReceipt!.id)!}} onBoosterChoice={(card:BoosterCard)=>{if(card!=='empty')useBoosterInventory.getState().grant(card)}}/>}
function Defeat(){const setScreen=useGame.getState().setScreen;const challenge=!!lastReceipt?.challenge;return <BattleResult receipt={lastReceipt} onHome={()=>{pendingDefeatCheckpoint=null;challenge?setScreen('crystal'):goToLobby()}} onNext={()=>{pendingDefeatCheckpoint=null;setScreen(challenge?'crystal':'loadout')}} onRevive={()=>{if(!pendingDefeatCheckpoint)return;activeReviveCheckpoint=pendingDefeatCheckpoint;pendingDefeatCheckpoint=null;setScreen('battle')}} onDouble={()=>{}}/>}
function BattleV2(){const {level,coins,unitLevels,weaponLevels,equippedUnit,equippedWeapon,unitSkins,sfx,setScreen}=useGame();const ownedSkins=useSkinInventory(state=>state.owned);const [checkpoint]=useState(()=>activeReviveCheckpoint||undefined);const [loadout]=useState(()=>({level:selectedBattleLevel(level),unitIndex:equippedUnit,weaponIndex:equippedWeapon,unitLevel:unitLevels[equippedUnit]||1,weaponLevel:weaponLevels[equippedWeapon]||1,challenge:sessionStorage.getItem('mobo-crystal-challenge')==='true',skin:ownedSkins.includes(unitSkins[equippedUnit])?unitSkins[equippedUnit]:'default'}));useEffect(()=>{activeReviveCheckpoint=null;return()=>{sessionStorage.removeItem('mobo-crystal-challenge')}},[]);return <BattleScreen loadout={loadout} checkpoint={checkpoint} coins={coins} sfx={sfx} onEnd={completeBattle} onExit={goToLobby} onRetry={()=>setScreen('loadout')}/>}
function WeaponCard({item,index,itemLevel,cost,required,unlocked,owned,isEquipped,coins,onAction}:{item:string[];index:number;itemLevel:number;cost:number;required:number;unlocked:boolean;owned:boolean;isEquipped:boolean;coins:number;onAction:()=>void}){
  const progress=Math.min(100,Math.max(0,((itemLevel-1)/(ECONOMY.maxUpgradeLevel-1))*100)),canUpgrade=owned&&isEquipped&&itemLevel<ECONOMY.maxUpgradeLevel&&coins>=cost;
  const damage=Number(item[2])+itemLevel*10;
  const actionLabel=!unlocked?<>LEVEL {required}</>:!owned?<>BUY <small><CurrencyIcon kind="coin" size={18}/>{unlockCost('weapon',index).toLocaleString()}</small></>:isEquipped?itemLevel>=ECONOMY.maxUpgradeLevel?'MAX LEVEL':<>UPGRADE <small><CurrencyIcon kind="coin" size={16}/>{cost.toLocaleString()}</small></>:'EQUIP';
  return <article className={`weapon-card weapon-rarity-${String(item[1]).toLowerCase()} ${isEquipped?'equipped ':''}${!unlocked?'locked-item ':''}${unlocked&&!owned?'purchase-item':''}`}><div className="weapon-card-art"><img className={!unlocked?'weapon-locked-art':''} src={weaponArt[index]} alt={item[0]}/>{!unlocked&&<span className="weapon-lock-badge">LOCKED</span>}</div><div className="weapon-card-main"><div className="weapon-card-head"><div><b>{item[0]}</b><em>{item[1]}</em></div>{isEquipped&&<span className="weapon-equipped">EQUIPPED</span>}</div><small className="weapon-card-status">{!unlocked?`UNLOCK AT LEVEL ${required}`:!owned?'AVAILABLE · PURCHASE REQUIRED':isEquipped?`LEVEL ${itemLevel} / ${ECONOMY.maxUpgradeLevel}`:'READY TO EQUIP'}</small><div className="weapon-stat-grid"><span className="weapon-stat"><i className="weapon-stat-glyph damage" aria-hidden="true"/><b>{damage}</b><small>DAMAGE</small></span><span className="weapon-stat"><i className="weapon-stat-glyph speed" aria-hidden="true"/><b>{item[3]}</b><small>FIRE RATE</small></span><span className="weapon-stat"><i className="weapon-stat-glyph range" aria-hidden="true"/><b>{item[4]}</b><small>RANGE</small></span></div><div className="weapon-progress"><div><small>UPGRADE</small><b>{itemLevel} / {ECONOMY.maxUpgradeLevel}</b></div><span><i style={{width:`${progress}%`}}/></span></div></div><Button secondary onClick={onAction}>{actionLabel}</Button>{canUpgrade&&<i className="weapon-up-indicator" aria-label="Upgrade available">↑</i>}</article>
}
function UnitCard({item,index,itemLevel,cost,required,unlocked,owned,isEquipped,coins,skin,onAction}:{item:string[];index:number;itemLevel:number;cost:number;required:number;unlocked:boolean;owned:boolean;isEquipped:boolean;coins:number;skin:SkinId;onAction:()=>void}){
  const progress=Math.min(100,Math.max(0,((itemLevel-1)/(ECONOMY.maxUpgradeLevel-1))*100)),canUpgrade=owned&&isEquipped&&itemLevel<ECONOMY.maxUpgradeLevel&&coins>=cost;
  const damage=Number(item[2])+itemLevel*10,health=Number(item[3])+itemLevel*5,speed=item[4];
  const actionLabel=!unlocked?<>LEVEL {required}</>:!owned?<>BUY <small><CurrencyIcon kind="coin" size={18}/>{unlockCost('unit',index).toLocaleString()}</small></>:isEquipped?itemLevel>=ECONOMY.maxUpgradeLevel?'MAX LEVEL':<>UPGRADE <small><CurrencyIcon kind="coin" size={16}/>{cost.toLocaleString()}</small></>:'EQUIP';
  const art=unlocked?unitSkinArt(index,skin):unitArt[index];
  return <article className={`unit-card weapon-rarity-${String(item[1]).toLowerCase()} ${isEquipped?'equipped ':''}${!unlocked?'locked-item ':''}${unlocked&&!owned?'purchase-item':''}`}><div className="weapon-card-art"><img className={!unlocked?'weapon-locked-art':''} src={art} alt={item[0]}/>{!unlocked&&<span className="weapon-lock-badge">LOCKED</span>}</div><div className="weapon-card-main"><div className="weapon-card-head"><div><b>{item[0]}</b><em>{item[1]}</em></div>{isEquipped&&<span className="weapon-equipped">EQUIPPED</span>}</div><small className="weapon-card-status">{!unlocked?`UNLOCK AT LEVEL ${required}`:!owned?'AVAILABLE · PURCHASE REQUIRED':isEquipped?`LEVEL ${itemLevel} / ${ECONOMY.maxUpgradeLevel}`:'READY TO EQUIP'}</small><div className="weapon-stat-grid"><span className="weapon-stat"><i className="weapon-stat-glyph damage" aria-hidden="true"/><b>{damage}</b><small>DAMAGE</small></span><span className="weapon-stat"><i className="weapon-stat-glyph health" aria-hidden="true"/><b>{health}</b><small>HEALTH</small></span><span className="weapon-stat"><i className="weapon-stat-glyph speed" aria-hidden="true"/><b>{speed}</b><small>SPEED</small></span></div><div className="weapon-progress"><div><small>UPGRADE</small><b>{itemLevel} / {ECONOMY.maxUpgradeLevel}</b></div><span><i style={{width:`${progress}%`}}/></span></div></div><Button secondary onClick={onAction}>{actionLabel}</Button>{canUpgrade&&<i className="weapon-up-indicator" aria-label="Upgrade available">↑</i>}</article>
}
function Collection({kind}:{kind:'units'|'weapons'}){
  const list=kind==='units'?units:weapons;
  const {unitLevels,weaponLevels,ownedUnits,ownedWeapons,unitSkins,upgrade,purchase,setScreen,equippedUnit,equippedWeapon,equip,vibration,level,notify,coins}=useGame();
  const levels=kind==='units'?unitLevels:weaponLevels,owned=kind==='units'?ownedUnits:ownedWeapons,equipped=kind==='units'?equippedUnit:equippedWeapon;
  const unlockLevels=kind==='units'?[1,11,21]:[1,11,21];
  const action=(index:number)=>{
    const type=kind==='units'?'unit':'weapon',required=unlockLevels[index];
    if(level<required){notify('Unlocks at Level '+required);VibrationService.error(vibration);return}
    if(!owned[index]){
      if(purchase(type,index)){VibrationService.success(vibration);AnalyticsService.track('item_purchased',{type,index,cost:unlockCost(type,index)})}
      else VibrationService.error(vibration);
      return
    }
    if(index!==equipped){equip(type,index);VibrationService.tap(vibration);AnalyticsService.track('equipment_changed',{type,index});return}
    const oldLevel=levels[index]||1,cost=upgradeCost(oldLevel,index);
    if(upgrade(type,index)){const newLevel=useGame.getState()[type==='unit'?'unitLevels':'weaponLevels'][index]||oldLevel;VibrationService.success(vibration);AnalyticsService.trackUpgrade(type,{itemId:`${type}_${index}`,oldLevel,newLevel,currency:'coins',cost})}
    else VibrationService.error(vibration)
  };
  return <><Header title={kind==='units'?'Units':'Weapons'}/><div className="tabs"><span className="selected">{kind==='units'?'Units':'Weapons'}</span>{kind==='units'&&<span onClick={()=>setScreen('skins')}>Skins</span>}</div><div className="collection">{list.map((x,i)=>{const itemLevel=levels[i]||1,cost=upgradeCost(itemLevel,i),required=unlockLevels[i],unlocked=level>=required,ownedItem=owned[i]===true,isEquipped=ownedItem&&i===equipped;if(kind==='weapons')return <WeaponCard key={x[0]} item={x} index={i} itemLevel={itemLevel} cost={cost} required={required} unlocked={unlocked} owned={ownedItem} isEquipped={isEquipped} coins={coins} onAction={()=>action(i)}/>;return <UnitCard key={x[0]} item={x} index={i} itemLevel={itemLevel} cost={cost} required={required} unlocked={unlocked} owned={ownedItem} isEquipped={isEquipped} coins={coins} skin={unitSkins[i]||'default'} onAction={()=>action(i)}/>})}</div></>}
type ShopTab='Featured'|'Gems'|'Boosters';
type CurrencyPack={name:string;coins:number;gems:number;description:string;tone:'gold'|'purple'|'blue';productId:PaidProductId;priceUsd:number;badge?:string;icon?:'coin'|'gem'|'blackgold'};
function requestStorePayment(productId:PaidProductId,title:string,priceUsd:number,notify:(message:string)=>void,vibration:boolean){const product=PaymentService.getProduct(productId),catalogTitle=product?.title||title,catalogPrice=product?.priceUsd??priceUsd,result=PaymentService.requestPurchase(productId),status=result.status==='not-configured'?'Payment service is not connected yet':'Purchase started';notify(`${catalogTitle}: ${status}`);VibrationService.tap(vibration);AnalyticsService.trackPurchaseStarted({productId,title:catalogTitle,priceUsd:catalogPrice,transactionId:result.transactionId,status:result.status});return result}
function formatPrice(priceUsd:number){return `$${priceUsd.toFixed(2)}`}
function PackVisual({pack}:{pack:CurrencyPack}){const tier=pack.productId==='shop-mixed-small'?'small':pack.productId==='shop-mixed-medium'?'medium':'large';const art=tier==='small'?shopChestFullArt:tier==='medium'?shopChestOverflowArt:shopChestSpillingArt;return <strong className={`shop-pack-icon shop-pack-visual shop-pack-visual-${tier}`} aria-hidden="true"><img src={art} alt=""/><em>{tier==='large'?'MAX VALUE':tier==='medium'?'BEST VALUE':'QUICK BOOST'}</em></strong>}
function GemPackVisual({pack}:{pack:CurrencyPack}){const tier=pack.productId==='shop-gems-small'?'small':pack.productId==='shop-gems-medium'?'medium':'large';const art=tier==='small'?gemPouchArt:tier==='medium'?gemSatchelArt:gemVaultArt;return <strong className={`shop-pack-icon shop-pack-visual gem-pack-visual gem-pack-visual-${tier}`} aria-hidden="true"><img src={art} alt=""/><em>{tier==='large'?'CRYSTAL VAULT':tier==='medium'?'CRYSTAL CACHE':'CRYSTAL POUCH'}</em></strong>}
function CurrencyPackCard({pack,onPurchase}:{pack:CurrencyPack;onPurchase:()=>void}){return <article className={`shopcard shop-pack ${pack.tone} ${pack.icon==='blackgold'?'shop-pack-blackgold':''}`}><div className="shop-pack-copy">{pack.badge&&<span className="shop-pack-badge">{pack.badge}</span>}<b>{pack.name}</b><small>{pack.description}</small><p>{pack.coins?<CurrencyValue kind="coin" value={pack.coins.toLocaleString()}/>:null}{pack.gems?<CurrencyValue kind="gem" value={pack.gems}/>:null}</p></div>{pack.icon==='blackgold'?<strong className="shop-pack-icon shop-pack-blackgold-icon"><img src={unitSkinArt(2,'blackgold')} alt="Black-Gold skin"/></strong>:pack.coins?<PackVisual pack={pack}/>:<GemPackVisual pack={pack}/>}<Button onClick={onPurchase}>BUY {formatPrice(pack.priceUsd)}</Button></article>}
function Shop(){
  const {removeAds,vibration,notify}=useGame();
  const starterOffer=useStarterOffer();
  const [tab,setTab]=useState<ShopTab>('Featured');
  const purchase=(productId:PaidProductId,title:string,priceUsd:number)=>requestStorePayment(productId,title,priceUsd,notify,vibration);
  const buyStarter=()=>{const result=purchase('starter-royal-pack','Royal Starter Pack',2.99);if(result.status!=='not-configured')starterOffer.markPurchased()};
  const buyBlackGold=()=>{const result=purchase('shop-royal-pack','Black Gold Set',14.99);if(result.status!=='not-configured')starterOffer.markPurchased()};
  const specialPacks:CurrencyPack[]=[{name:'SMALL SUPPLY',coins:5000,gems:50,description:'5,000 coins + 50 crystals',tone:'blue',productId:'shop-mixed-small',priceUsd:.99},{name:'COMMANDER PACK',coins:15000,gems:150,description:'15,000 coins + 150 crystals',tone:'purple',productId:'shop-mixed-medium',priceUsd:1.99,badge:'BEST VALUE'},{name:'WAR CHEST',coins:50000,gems:500,description:'50,000 coins + 500 crystals',tone:'gold',productId:'shop-mixed-large',priceUsd:5.99}];
  const gemPacks:CurrencyPack[]=[{name:'GEM POUCH',coins:0,gems:100,description:'100 crystals for your next upgrade',tone:'blue',productId:'shop-gems-small',priceUsd:.99},{name:'GEM CACHE',coins:0,gems:300,description:'300 crystals for boosters',tone:'purple',productId:'shop-gems-medium',priceUsd:1.99,badge:'POPULAR'},{name:'GEM VAULT',coins:0,gems:900,description:'900 crystals for your strongest upgrades',tone:'gold',productId:'shop-gems-large',priceUsd:4.99}];
  const renderPacks=(packs:CurrencyPack[])=>packs.map(pack=><CurrencyPackCard key={pack.name} pack={pack} onPurchase={()=>purchase(pack.productId,pack.name,pack.priceUsd)}/>);
  return <div className="shop-section-screen"><Header title="Shop"/><div className="tabs">{(['Featured','Gems','Boosters'] as const).map(name=><span className={tab===name?'selected':''} onClick={()=>setTab(name)} key={name}>{name}</span>)}</div>{tab==='Boosters'?<BoosterStore/>:<div className="shop">{tab==='Featured'?<><div className="shop-section-title"><b>SPECIAL PACKS</b><small>Fixed rewards · premium value for every commander</small></div>{starterOffer.isActive?<StarterPackPromo remainingMs={starterOffer.remainingMs} onPurchase={buyStarter} ctaLabel="BUY NOW · $2.99"/>:!starterOffer.purchased?<StarterPackPromo variant="standard" onPurchase={buyBlackGold}/>:null} {renderPacks(specialPacks)}<article className="shopcard"><b>REMOVE ADS</b><strong>🚫</strong><p>{removeAds?'Ads removed':'Enjoy the game without ads!'}</p><Button onClick={()=>removeAds?notify('Remove Ads is already active'):purchase('shop-remove-ads','Remove Ads',2.99)}>{removeAds?'OWNED':'BUY $2.99'}</Button></article></>:renderPacks(gemPacks)}</div>}</div>}
function Profile(){const {setScreen,wins,level,coins}=useGame();const [playerName,setPlayerName]=useState(readPlayerName);const [editing,setEditing]=useState(false);const [draft,setDraft]=useState(playerName);const levelProgress=Math.min(100,Math.max(0,level)/50*100);const achievementNotice=hasUnclaimedAchievement(wins,level,coins);const openAchievements=()=>{localStorage.setItem('mobo-notice-achievements-seen','true');setScreen('achievements')};const beginEdit=()=>{setDraft(playerName);setEditing(true)};const saveName=()=>{const next=draft.trim().slice(0,18);if(!next)return;localStorage.setItem('mobo-player-name-v1',next);setPlayerName(next);setEditing(false);window.dispatchEvent(new Event('mobo-player-name-changed'))};const cancelEdit=()=>{setDraft(playerName);setEditing(false)};return <><Header title="Profile"/><div className="profile"><div className="profilehero"><div className="avatar huge"><img src={lobbyCommanderAvatar} alt="Commander"/></div><div className="profileidentity">{editing?<div className="profile-name-editor"><input value={draft} maxLength={18} autoFocus aria-label="Player name" onChange={event=>setDraft(event.target.value)} onKeyDown={event=>{if(event.key==='Enter')saveName();if(event.key==='Escape')cancelEdit()}}/><button type="button" onClick={saveName} aria-label="Save player name">✓</button><button type="button" onClick={cancelEdit} aria-label="Cancel name editing">×</button></div>:<div className="profile-name-row"><h2>{playerName}</h2><button type="button" className="name-edit-button" onClick={beginEdit} aria-label="Edit player name">✎</button></div>}<div className="profile-level-row"><small>Level {level} / 50</small><div className="profile-level-track"><i style={{width:levelProgress+'%'}}/></div></div></div></div><div className="stats"><span><b>{wins}</b>Battles</span><span><b>{wins}</b>Wins</span><span><b>{wins?100:0}%</b>Win Rate</span><span><b>{wins*18}</b>Enemies</span></div><div className="profilebuttons"><Button secondary onClick={()=>setScreen('stats')}>▥ Statistics</Button><Button secondary onClick={openAchievements}>🏆 Achievements {achievementNotice&&<i className="notice-dot" aria-hidden="true"/>}</Button><Button secondary onClick={()=>setScreen('settings')}>⚙ Settings</Button></div></div></>}
function Stats(){const {wins,level,coins,gems,unitLevels,weaponLevels,equippedUnit,equippedWeapon}=useGame();const battleReceipts=journal.receipts.filter(receipt=>!receipt.challenge),victories=battleReceipts.filter(receipt=>receipt.result==='victory').length,winRate=battleReceipts.length?Math.round(victories/battleReceipts.length*100):0;const unitLevel=unitLevels[equippedUnit]||1,weaponLevel=weaponLevels[equippedWeapon]||1;return <><Header title="Statistics"/><div className="stats-hero"><span>⚔</span><div><b>COMMANDER REPORT</b><small>Season 1 · Green Kingdom</small></div></div><div className="stat-cards"><article><b>{wins}</b><small>Victories</small></article><article><b>{level}</b><small>Current Level</small></article><article><b>{winRate}%</b><small>Win Rate</small></article><article><b>{wins*18}</b><small>Robots Defeated</small></article></div><div className="report-card"><b>ARMY POWER</b><p><span>Equipped unit</span><strong>Lv. {unitLevel}</strong></p><p><span>Equipped weapon</span><strong>Lv. {weaponLevel}</strong></p><p><span>Resources collected</span><strong><CurrencyValue kind="coin" value={coins.toLocaleString()}/><CurrencyValue kind="gem" value={gems}/></strong></p><div className="report-meter"><i style={{width:`${Math.min(100,(unitLevel+weaponLevel)*10)}%`}}/></div><small>Keep upgrading to improve your battlefield power.</small></div><div className="report-card"><b>NEXT MILESTONE</b><p><span>Reach Level {Math.ceil(level/5)*5+1}</span><strong>{level%5}/5</strong></p><div className="report-meter"><i style={{width:`${(level%5)*20}%`}}/></div></div></>}
function Achievements(){const {wins,level,addCoins,notify,vibration}=useGame();const [claimed,setClaimed]=useState<number[]>(()=>safeArray('mobo-achievement-claimed'));const cards=[['First Victory','Win your first battle',wins>=1,100],['Growing Army','Reach Level 5',level>=5,250],['Level 10 Hero','Reach Level 10',level>=10,300],['Frozen Lands','Unlock World 2',level>=11,400],['Ten Wins','Win 10 battles',wins>=10,500],['Runner Unlocked','Reach Level 12',level>=12,600],['Boss Hunter','Defeat a boss',wins>=10,700],['Dark Forest','Unlock World 3',level>=21,800],['Coin Collector','Earn 5,000 coins',Number(localStorage.getItem('mobo-coins-v2')||0)>=5000,900],['Perfect Start','Win 5 battles in a row',wins>=5,1000],['Tank Commander','Reach Level 25',level>=25,1100],['Wasteland','Unlock World 4',level>=31,1200],['Veteran','Win 25 battles',wins>=25,1400],['Arsenal Master','Reach Level 35',level>=35,1600],['Lava Walker','Unlock World 5',level>=41,1800],['Elite Commander','Reach Level 50',level>=50,2200],['Rich Commander','Earn 25,000 coins',Number(localStorage.getItem('mobo-coins-v2')||0)>=25000,2600],['Battle Marathon','Win 50 battles',wins>=50,3000],['World Conqueror','Complete all 50 levels',level>=50,4000],['Legendary General','Win 100 battles',wins>=100,6000]];const claim=(index:number,reward:number)=>{if(claimed.includes(index))return;const next=[...claimed,index];setClaimed(next);localStorage.setItem('mobo-achievement-claimed',JSON.stringify(next));addCoins(reward);VibrationService.success(vibration);notify(`Achievement reward +${reward} coins`);AnalyticsService.track('achievement_claimed',{index,reward})};return <><Header title="Achievements"/><div className="achievement-list">{cards.map(([title,description,done,reward],index)=>{const isClaimed=claimed.includes(index);return <article className={done?'achievement earned':'achievement'} key={String(title)}><span>{done?'🏆':'🔒'}</span><div><b>{title}</b><small>{description}</small><small className="achievement-reward">🪙 {reward}</small></div>{done&&!isClaimed?<button onClick={()=>claim(index,Number(reward))}>CLAIM</button>:<em>{isClaimed?'CLAIMED':done?'READY':'LOCKED'}</em>}</article>})}</div></>}
function DebugPanel(){const {addCoins,addGems,win,setScreen,setUnitSkin,notify}=useGame();if(!import.meta.env.DEV)return null;const reset=()=>{Object.keys(localStorage).filter(key=>key.startsWith('mobo-')).forEach(key=>localStorage.removeItem(key));Object.values(STARTER_OFFER_KEYS).forEach(key=>localStorage.removeItem(key));window.location.reload()};const unlockSkins=()=>{(['ninja','knight','cyber','golden','blackgold'] as SkinId[]).forEach(skin=>useSkinInventory.getState().grant(skin));setUnitSkin(0,'blackgold');setUnitSkin(1,'blackgold');setUnitSkin(2,'blackgold');notify('All skins unlocked · Black Gold equipped')};return <details className="debug-panel"><summary>DEV</summary><div><button onClick={()=>addCoins(100000)}>+100000 🪙</button><button onClick={()=>addGems(100)}>+100 💎</button><button onClick={unlockSkins}>Unlock all skins</button><button onClick={win}>Next level</button><button onClick={()=>setScreen('result')}>Win</button><button onClick={()=>setScreen('defeat')}>Lose</button><button className="danger" onClick={reset}>Reset save</button></div></details>}
