function Support(){
  const {language,notify}=useGame();
  const russian=language==='ru';
  const [subject,setSubject]=useState('');
  const [message,setMessage]=useState('');
  const send=()=>{
    const text=message.trim();
    if(!text){notify(russian?'Опиши проблему перед отправкой':'Describe the issue before sending');return}
    const body=[russian?'Сообщение из Mobo War':'Message from Mobo War',`Subject: ${subject.trim()||'Game feedback'}`,text,'',`App language: ${language}`].join('\n\n');
    window.location.href=`mailto:hkehke31@gmail.com?subject=${encodeURIComponent(subject.trim()||'Mobo War support')}&body=${encodeURIComponent(body)}`;
    AnalyticsService.track('support_email_opened',{hasSubject:Boolean(subject.trim())});
  };
  return <><Header title="Support"/><article className="support-page legal-page"><div className="legal-hero"><span>MOBO WAR · COMMANDER CARE</span><h1>{russian?'Поддержка':'Support'}</h1><small>{russian?'Мы ответим через почтовое приложение устройства.':'Your mail app will open with a prepared support message.'}</small></div><label>{russian?'Тема':'Subject'}<input value={subject} onChange={event=>setSubject(event.target.value)} maxLength={80} placeholder={russian?'Например: проблема в бою':'For example: battle issue'}/></label><label>{russian?'Сообщение':'Message'}<textarea value={message} onChange={event=>setMessage(event.target.value)} maxLength={2000} rows={7} placeholder={russian?'Опиши, что произошло...':'Tell us what happened...'}/></label><Button onClick={send}>{russian?'ОТПРАВИТЬ В ПОДДЕРЖКУ':'EMAIL SUPPORT'}</Button></article></>}
function PrivacyPolicy(){
  const {language}=useGame();
  const russian=language==='ru';
  const sections=russian?[
    ['1. Какие данные используются','Игра хранит локально на устройстве прогресс, настройки, выбранные юниты и скины, имя игрока и историю игровых результатов.'],
    ['2. Для чего они нужны','Эти данные нужны для сохранения прогресса, показа статистики, работы наград, миссий и персонализации игры.'],
    ['3. Покупки','Платёжные данные не вводятся и не хранятся в игре. После подключения магазина покупки будут обрабатываться выбранной платформой по её правилам.'],
    ['4. Аналитика','Игровые события могут использоваться в обезличенном виде для проверки баланса и стабильности функций. Мы не продаём личные данные игроков.'],
    ['5. Удаление данных','Удаление приложения или очистка его данных удаляет локальный прогресс. Перед этим убедись, что тебе не нужно сохранять тестовый прогресс.'],
    ['6. Дети и безопасность','Не вводи пароли, данные карт или другие чувствительные сведения в игровых полях. Если ты несовершеннолетний, используй игру с разрешения взрослого.'],
    ['7. Изменения','Политика может обновляться вместе с игрой. Важные изменения будут отражаться в новой версии этого экрана.'],
  ]:[
    ['1. Data used','The game stores progress, settings, selected units and skins, player name, and gameplay results locally on your device.'],
    ['2. Why it is used','This data is needed to save progress, show statistics, operate rewards and missions, and personalize the game.'],
    ['3. Purchases','Payment details are not entered or stored in the game. Once a store is connected, purchases will be handled by the selected platform under its rules.'],
    ['4. Analytics','Gameplay events may be used in an aggregated form to balance the game and check feature stability. We do not sell players’ personal data.'],
    ['5. Deleting data','Removing the app or clearing its data removes local progress. Make sure you do not need the test progress before doing so.'],
    ['6. Children and safety','Do not enter passwords, card details, or other sensitive information into game fields. Minors should use the game with an adult’s permission.'],
    ['7. Changes','This policy may be updated with the game. Important changes will be reflected in a new version of this screen.'],
  ];
  return <><Header title="Privacy Policy"/><article className="legal-page"><div className="legal-hero"><span>MOBO WAR · DATA CARE</span><h1>{russian?'Политика конфиденциальности':'Privacy Policy'}</h1><small>{russian?'Дата вступления в силу: 17 сентября 2026':'Effective date: September 17, 2026'}</small></div>{sections.map(([title,body])=><section key={title}><h2>{title}</h2><p>{body}</p></section>)}<small className="legal-footer">{russian?'По вопросам конфиденциальности обратись в Support.':'For privacy questions, contact Support from the game settings.'}</small></article></>}
type MissionEntry={name:string;current:number;target:number;reward:number;gems?:number};
function Missions(){
  const {wins,unitLevels,weaponLevels,addCoins,addGems,notify,vibration,level}=useGame();
  const [tab,setTab]=useState<'Daily'|'Weekly'>('Daily');
  const dailyKey=TimeService.dayKey(),weeklyKey=missionWeekKey();
  const upgradeTotal=unitLevels.reduce((sum,itemLevel)=>sum+Math.max(0,itemLevel-1),0)+weaponLevels.reduce((sum,itemLevel)=>sum+Math.max(0,itemLevel-1),0);
  const bossWins=journal.receipts.filter(receipt=>receipt.result==='victory'&&!receipt.challenge&&receipt.level%10===0).length;
  const counter=(key:string,value:number)=>Math.max(0,value-missionCounter(key,value));
  const dailyWins=counter(`mobo-mission-daily-wins-${dailyKey}`,wins),weeklyWins=counter(`mobo-mission-weekly-wins-${weeklyKey}`,wins);
  const dailyUpgrades=counter(`mobo-mission-daily-upgrades-${dailyKey}`,upgradeTotal),weeklyUpgrades=counter(`mobo-mission-weekly-upgrades-${weeklyKey}`,upgradeTotal);
  const dailyBosses=counter(`mobo-mission-daily-bosses-${dailyKey}`,bossWins),weeklyBosses=counter(`mobo-mission-weekly-bosses-${weeklyKey}`,bossWins);
  const safeLevel=Math.max(1,level),rewardBase=RewardsService.battleCoins(safeLevel,3),gemBase=RewardsService.battleGems(safeLevel);
  const missionReward=(multiplier:number)=>Math.max(100,Math.round(rewardBase*multiplier/50)*50);
  const missionGems=(multiplier:number)=>Math.max(2,Math.round(gemBase*multiplier*1.2));
  type MissionTemplate={name:string;kind:'wins'|'upgrades'|'bosses';target:number;reward:number;gems?:number};
  const dailyPool:MissionTemplate[]=[
    {name:'Win 8 battles',kind:'wins',target:8,reward:.65},{name:'Win 12 battles',kind:'wins',target:12,reward:.9},{name:'Win 15 battles',kind:'wins',target:15,reward:1.1},
    {name:'Upgrade 2 units or weapons',kind:'upgrades',target:2,reward:.8},{name:'Upgrade 3 units or weapons',kind:'upgrades',target:3,reward:1},{name:'Upgrade 4 units or weapons',kind:'upgrades',target:4,reward:1.25},
    {name:'Defeat 2 bosses',kind:'bosses',target:2,reward:1.3},{name:'Defeat 3 bosses',kind:'bosses',target:3,reward:1.7},{name:'Win 10 battles',kind:'wins',target:10,reward:.75},
    {name:'Upgrade 5 units or weapons',kind:'upgrades',target:5,reward:1.45},{name:'Win 18 battles',kind:'wins',target:18,reward:1.35},{name:'Defeat a boss',kind:'bosses',target:1,reward:1}
  ];
  const weeklyPool:MissionTemplate[]=[
    {name:'Win 12 battles',kind:'wins',target:12,reward:2.7,gems:1},{name:'Win 18 battles',kind:'wins',target:18,reward:3.8,gems:1.2},{name:'Win 25 battles',kind:'wins',target:25,reward:5,gems:1.5},{name:'Win 35 battles',kind:'wins',target:35,reward:6.5,gems:2},
    {name:'Upgrade 5 units or weapons',kind:'upgrades',target:5,reward:3.4,gems:1},{name:'Upgrade 8 units or weapons',kind:'upgrades',target:8,reward:4.5,gems:1.3},{name:'Upgrade 12 units or weapons',kind:'upgrades',target:12,reward:6,gems:1.7},{name:'Upgrade 16 units or weapons',kind:'upgrades',target:16,reward:7.5,gems:2},
    {name:'Defeat 2 bosses',kind:'bosses',target:2,reward:4.3,gems:1.5},{name:'Defeat 3 bosses',kind:'bosses',target:3,reward:5.8,gems:2},{name:'Defeat 4 bosses',kind:'bosses',target:4,reward:7.5,gems:2.5},{name:'Win 30 battles',kind:'wins',target:30,reward:5.8,gems:1.8}
  ];
  const dayNumber=Math.floor(new Date(`${dailyKey}T00:00:00Z`).getTime()/86400000),weekNumber=Math.floor(new Date(`${weeklyKey}T00:00:00Z`).getTime()/86400000);
  const rotate=(pool:MissionTemplate[],offset:number)=>Array.from({length:4},(_,index)=>pool[(offset+index)%pool.length]);
  const dailyValues={wins:dailyWins,upgrades:dailyUpgrades,bosses:dailyBosses},weeklyValues={wins:weeklyWins,upgrades:weeklyUpgrades,bosses:weeklyBosses};
  const build=(template:MissionTemplate,values:typeof dailyValues):MissionEntry=>({name:template.name,current:Math.min(values[template.kind],template.target),target:template.target,reward:missionReward(template.reward),gems:template.gems?missionGems(template.gems):undefined});
  const dailyMissions=rotate(dailyPool,dayNumber).map(template=>build(template,dailyValues)),weeklyMissions=rotate(weeklyPool,Math.floor(weekNumber/7)).map(template=>build(template,weeklyValues));
  const dailyClaimKey=`mobo-mission-daily-claimed-${dailyKey}`,weeklyClaimKey=`mobo-mission-weekly-claimed-${weeklyKey}`;
  const [dailyClaimed,setDailyClaimed]=useState<number[]>(()=>localStorage.getItem(dailyClaimKey)?safeArray(dailyClaimKey):safeArray('mobo-mission-claimed'));
  const [weeklyClaimed,setWeeklyClaimed]=useState<number[]>(()=>safeArray(weeklyClaimKey));
  const entries=tab==='Daily'?dailyMissions:weeklyMissions,claimed=tab==='Daily'?dailyClaimed:weeklyClaimed;
  const weeklyReady=weeklyMissions.some((mission,index)=>mission.current>=mission.target&&!weeklyClaimed.includes(index));
  const claim=(index:number)=>{const mission=entries[index];if(!mission||claimed.includes(index)||mission.current<mission.target)return;const next=[...claimed,index],storageKey=tab==='Daily'?dailyClaimKey:weeklyClaimKey;tab==='Daily'?setDailyClaimed(next):setWeeklyClaimed(next);localStorage.setItem(storageKey,JSON.stringify(next));addCoins(mission.reward);if(mission.gems)addGems(mission.gems);VibrationService.success(vibration);notify(`${mission.name}: +${mission.reward} coins${mission.gems?` +${mission.gems} gems`:''}`);AnalyticsService.track('mission_claimed',{period:tab.toLowerCase(),index,reward:mission.reward,gems:mission.gems||0})};
  return <><Header title="Missions"/><div className="tabs mission-tabs">{(['Daily','Weekly'] as const).map(period=><span key={period} className={tab===period?'selected':''} onClick={()=>setTab(period)}>{period}{period==='Weekly'&&weeklyReady&&<i className="notice-dot tab-notice" aria-label="Weekly mission ready"/>}</span>)}</div><p className="subtitle mission-subtitle">{tab==='Daily'?`Refreshes every day · rewards scale with Level ${safeLevel}`:`Refreshes every Monday · rewards scale with Level ${safeLevel}`}</p><div className="mission-list">{entries.map((mission,index)=>{const complete=mission.current>=mission.target,wasClaimed=claimed.includes(index);return <article className="mission" key={`${tab}-${mission.name}`}><div><b>{mission.name}</b><small>{mission.current}/{mission.target}</small><div className="missionbar"><i style={{width:`${Math.min(100,(mission.current/mission.target)*100)}%`}}/></div></div><strong className="mission-reward"><CurrencyValue kind="coin" value={mission.reward}/>{mission.gems&&<CurrencyValue kind="gem" value={mission.gems}/>}</strong>{complete&&!wasClaimed&&<button className="mission-claim" onClick={()=>claim(index)}>CLAIM</button>}{wasClaimed&&<small className="mission-done">CLAIMED</small>}</article>})}</div></>}
function Daily(){
  const {dailyClaimed,claimDaily,vibration,notify}=useGame();
  const streak=Number(localStorage.getItem('mobo-daily-streak')||0),day=(streak-(dailyClaimed?1:0)+7)%7,claimedThrough=dailyClaimed?day:day-1;
  const rewards=[{coins:100},{coins:150,booster:'freeze' as const},{coins:200,gems:5},{coins:300,booster:'army' as const},{gems:12},{coins:500,booster:'blast' as const},{coins:1000,gems:25}];
  const boosterNames={freeze:'FREEZE',army:'+7 BOTS',blast:'BLAST'} as const;
  const claim=()=>{if(claimDaily()){const booster=rewards[day]?.booster;if(booster){useBoosterInventory.getState().grant(booster);notify(`Daily reward: ${boosterNames[booster]} added to inventory`)}VibrationService.success(vibration);AnalyticsService.track('daily_reward_claimed',{day:day+1,booster:booster||null})}};
  return <><Header title="Daily Login Rewards"/><p className="subtitle">Claim one reward each day and keep your streak alive. Boosters go straight to your battle inventory.</p><div className="daily-grid">{rewards.map((reward,i)=>{const claimed=i<=claimedThrough,booster=reward.booster;const copy=booster?`${reward.coins} COINS · ${boosterNames[booster]}`:reward.gems?`${reward.gems} GEMS${reward.coins?` · ${reward.coins} COINS`:''}`:`${reward.coins} COINS`;return <article className={claimed?'claimed-daily':!dailyClaimed&&i===day?'available':''} key={`day-${i}`}><b>Day {i+1}</b><span className="daily-reward-visual">{claimed?<CurrencyIcon kind="coin" size={42}/>:booster?<img src={boosterRewardArt[booster]} alt={boosterNames[booster]}/>:<CurrencyIcon kind={reward.gems?'gem':'coin'} size={42}/>}</span><small className="daily-reward-copy">{claimed?'CLAIMED':copy}</small></article>})}</div><Button onClick={claim}>{dailyClaimed?'CLAIMED TODAY':`CLAIM DAY ${day+1}`}</Button></>}
type PassReward={label:string;coins?:number;gems?:number;booster?:'freeze'|'army'|'blast';skin?:SkinId};
const passMissionClaims=()=>Object.keys(localStorage).filter(key=>key.startsWith('mobo-mission-daily-claimed-')||key.startsWith('mobo-mission-weekly-claimed-')).reduce((sum,key)=>sum+safeArray(key).length,0);
const passXpFor=(wins:number)=>wins*10+passMissionClaims()*5;
const passCoinReward=(level:number,tier:number,premium:boolean)=>{const base=RewardsService.battleCoins(Math.max(1,level),3),multiplier=(premium?1.1:.55)*(1+tier*.01);return Math.max(100,Math.round(base*multiplier/50)*50)};
const passGemReward=(level:number,tier:number,premium:boolean)=>Math.max(5,Math.round((5+Math.floor(Math.max(1,level)/10)*2)*(premium?1.5:1)*(1+tier*.02)));
const passRewardFor=(tier:number,track:PassTrack,level:number):PassReward=>{const premium=track==='premium';if(!premium&&tier===10)return {label:'NINJA SKIN',skin:'ninja'};if(!premium&&tier===20)return {label:'KNIGHT SKIN',skin:'knight'};if(!premium&&tier===30)return {label:'CYBER SKIN',skin:'cyber'};if(premium&&tier===50)return {label:'GOLDEN SKIN',skin:'golden'};const booster=(premium?({10:'blast',20:'army',30:'freeze',40:'blast'} as Record<number,'freeze'|'army'|'blast'>):({5:'freeze',15:'army',25:'blast',35:'freeze',45:'army'} as Record<number,'freeze'|'army'|'blast'>))[tier];if(booster)return {label:booster==='army'?'+7 BOTS':booster.toUpperCase(),booster};if(tier%5===0){const gems=passGemReward(level,tier,premium);return {label:`${gems} GEMS`,gems}}const coins=passCoinReward(level,tier,premium);return {label:`${coins.toLocaleString()} COINS`,coins}};
function PassRewardCard({track,reward,available,claimed,premiumUnlocked,onClaim}:{track:PassTrack;reward:PassReward;available:boolean;claimed:boolean;premiumUnlocked:boolean;onClaim:()=>void}){const locked=track==='premium'&&!premiumUnlocked;const visual=reward.skin?<img src={unitSkinArt(0,reward.skin)} alt=""/>:reward.booster?<img src={boosterRewardArt[reward.booster]} alt=""/>:<CurrencyIcon kind={reward.gems?'gem':'coin'} size={46}/>;return <article className={`pass-reward-card ${track}-pass-reward ${claimed?'claimed-pass':''} ${available&&!locked?'available-pass':''}`}><span className="pass-reward-visual">{visual}</span><b>{reward.label}</b><small>{reward.skin?`+${reward.skin==='default'?0:reward.skin==='ninja'?5:reward.skin==='knight'?10:reward.skin==='cyber'?15:20}% DMG · SPD · ARMOR`:reward.booster?'Added to inventory':track==='premium'?'Premium reward':'Free reward'}</small>{claimed?<em>CLAIMED</em>:locked?<button onClick={onClaim}>PREMIUM</button>:available?<button onClick={onClaim}>CLAIM</button>:<em>LOCKED</em>}</article>}
function Pass(){const {language}=useGame();const russian=language==='ru';return <><Header title="Battle Pass"/><article className="pass-disabled"><span className="pass-disabled-mark">✦</span><b>{russian?'Боевой пропуск временно отключён':'Battle Pass temporarily disabled'}</b><p>{russian?'Мы вернём этот раздел в одном из следующих обновлений. Все скины боевого пропуска теперь можно открыть за гемы в разделе Skins.':'We will bring this feature back in a future update. Battle Pass skins are now available for gems in the Skins section.'}</p></article></>}
function Skins(){const {unitSkins,setUnitSkin,equippedUnit,vibration,notify,gems,addGems}=useGame();const ownedSkins=useSkinInventory(state=>state.owned);const [unit,setUnit]=useState(equippedUnit);const skinNames=[['Default Blue','Shadow Ninja','Crown Knight','Neon Cyber','Golden Guard','Black Gold Elite'],['Runner Blue','Phantom Runner','Vanguard Runner','Neon Sprint','Golden Dash','Black Gold Sprinter'],['Tank Blue','Steel Sentinel','Royal Bastion','Cyber Fortress','Golden Bulwark','Black Gold Colossus']] as const;const skins:[SkinId,string,number][]=[['default','Always available',0],['ninja','600 gems',600],['knight','1,200 gems',1200],['cyber','2,200 gems',2200],['golden','4,000 gems',4000],['blackgold','Black Gold Set · $14.99',0]];const skinBonuses:Record<SkinId,number>={default:0,ninja:5,knight:10,cyber:15,golden:20,blackgold:40};const equipSkin=(id:SkinId,cost:number)=>{const alreadyOwned=ownedSkins.includes(id);if(!alreadyOwned){if(id==='blackgold'){notify('Available in the Black Gold Set');VibrationService.error(vibration);return}if(gems<cost){notify(`Need ${cost-gems} more gems`);VibrationService.error(vibration);return}addGems(-cost);useSkinInventory.getState().grant(id);notify(`${skinNames[unit][skins.findIndex(item=>item[0]===id)]} purchased for gems`)}setUnitSkin(unit,id);VibrationService.success(vibration);AnalyticsService.track('skin_equipped',{id,unit,gemCost:alreadyOwned?0:cost})};return <><Header title="Customization"/><div className="tabs unit-skin-tabs">{units.map((bot,index)=><span key={bot[0]} className={unit===index?'selected':''} onClick={()=>setUnit(index)}>{bot[0]}</span>)}</div><div className="skin-owner"><img src={unitSkinArt(unit,unitSkins[unit]||'default')} alt={units[unit][0]}/><div><small>SELECTING SKINS FOR</small><b>{units[unit][0]}</b></div></div><div className="skin-grid">{skins.map(([id,requirement,cost],index)=>{const unlocked=ownedSkins.includes(id),selected=unlocked&&unitSkins[unit]===id,price=id==='default'?'FREE':id==='blackgold'?'BLACK GOLD SET · $14.99':<span className="skin-gem-price"><CurrencyIcon kind="gem" size={16}/>{cost.toLocaleString()}</span>;return <button key={id} className={`skin-card skin-${id} ${selected?'selected-skin':''} ${!unlocked?'locked-skin':''}`} onClick={()=>equipSkin(id,cost)}><img src={unitSkinArt(unit,id)} alt=""/><b>{skinNames[unit][index]}</b><small className="skin-price">{price}</small><small>{unlocked?(selected?'EQUIPPED':'EQUIP'):id==='blackgold'?`LOCKED · ${requirement}`:'LOCKED'}</small><small className="skin-bonus">{skinBonuses[id]?'+'+skinBonuses[id]+'% DMG · SPD · ARMOR':'NO COMBAT BONUS'}</small></button>})}</div></>}
function CrystalChallenge(){const {setScreen,level,notify,vibration}=useGame();const today=TimeService.dayKey();const savedDate=localStorage.getItem('mobo-crystal-date');const initialTickets=savedDate===today?Number(localStorage.getItem('mobo-crystal-tickets')||3):3;const [tickets,setTickets]=useState(Math.max(0,Math.min(3,initialTickets)));const start=()=>{if(!tickets){notify('Come back tomorrow for more Crystal Challenges');VibrationService.error(vibration);return}const next=tickets-1;setTickets(next);localStorage.setItem('mobo-crystal-date',today);localStorage.setItem('mobo-crystal-tickets',String(next));sessionStorage.setItem('mobo-crystal-challenge','true');sessionStorage.setItem('mobo-selected-level',String(Math.max(1,level)));VibrationService.tap(vibration);setScreen('loadout')};return <><Header title="Crystal Challenge"/><div className="report-card crystal-challenge-card"><div className="stats-hero"><CurrencyIcon kind="gem" size={42}/><div><b>CRYSTAL RUSH</b><small>Hard bonus battle · x2 crystal reward</small></div></div><h2>Earn extra crystals</h2><p>Complete a difficult bonus battle and receive double crystals after victory.</p><strong className="crystal-reward"><CurrencyValue kind="gem" value="x2"/></strong><small>Attempts today: {tickets}/3</small><Button onClick={start}>{tickets?'START CHALLENGE':'COME BACK TOMORROW'}</Button></div></>}
function StarterOfferOverlay(){const offer=useStarterOffer();const {notify,vibration}=useGame();const [open,setOpen]=useState(false),[source,setSource]=useState('first_login');const launchPopupShown=useRef(false);const remainingSeconds=Math.max(0,Math.floor(offer.remainingMs/1000));const show=(nextSource:string)=>{setSource(nextSource);setOpen(true);AnalyticsService.trackPromoView(nextSource,remainingSeconds)};useEffect(()=>{if(!launchPopupShown.current&&offer.isActive){launchPopupShown.current=true;offer.markShown();show('first_login')}},[offer.isActive]);useEffect(()=>{const handleOpen=(event:Event)=>{if(offer.isActive)show((event as CustomEvent<{source?:string}>).detail?.source||'lobby')};window.addEventListener(STARTER_OFFER_EVENT,handleOpen);return()=>window.removeEventListener(STARTER_OFFER_EVENT,handleOpen)},[offer.isActive,remainingSeconds]);const close=()=>{AnalyticsService.trackPromoClose(source,remainingSeconds);offer.markClosed();setOpen(false)};const buy=()=>{AnalyticsService.trackPromoClick(source,remainingSeconds);AnalyticsService.trackPromoPurchaseStarted(source,remainingSeconds);const result=requestStorePayment('starter-royal-pack','Royal Starter Pack',2.99,notify,vibration);if(result.status!=='not-configured'){offer.markPurchased();AnalyticsService.trackPromoPurchaseSuccess(source,remainingSeconds,result.transactionId);setOpen(false)}};if(!open||!offer.isActive)return null;return <StarterOfferModal remainingMs={offer.remainingMs} onClose={close} onPurchase={buy}/>}
function App(){useEffect(()=>{const current=useGame.getState().screen;const state=window.history.state as {moboWar?:boolean;screen?:Screen;appDepth?:number}|null;const appDepth=state?.moboWar===true&&Number.isInteger(state.appDepth)?Number(state.appDepth):0;if(state?.moboWar!==true||state.screen!==current||state.appDepth!==appDepth)window.history.replaceState({...state,moboWar:true,screen:current,appDepth},'',window.location.href);const handleBack=(event:PopStateEvent)=>{const next=event.state as {moboWar?:boolean;screen?:Screen;appDepth?:number}|null;const active=useGame.getState().screen;if(next?.moboWar===true&&next.screen){useGame.getState().setScreen(next.screen,true);return}if(active!=='lobby'){window.history.pushState({moboWar:true,screen:'lobby',appDepth:0},'',window.location.href);useGame.getState().setScreen('lobby',true)}};window.addEventListener('popstate',handleBack);return()=>window.removeEventListener('popstate',handleBack)},[]);useEffect(()=>{let mounted=true;let listener:{remove:()=>Promise<void>}|undefined;void CapacitorApp.addListener('backButton',()=>{const active=useGame.getState().screen;if(active==='battle'){window.dispatchEvent(new Event('mobo-war-battle-back'));return}if(active!=='lobby'){AudioManager.stop('music');AudioManager.stop('sfx');window.history.replaceState({moboWar:true,screen:'lobby',appDepth:0},'',window.location.href);useGame.getState().setScreen('lobby',true);return}AudioManager.stop('music');AudioManager.stop('sfx');void CapacitorApp.exitApp().catch(()=>{})}).then((registered)=>{if(mounted)listener=registered;else void registered.remove()}).catch(()=>{});return()=>{mounted=false;void listener?.remove()}},[]);const {screen,toast,music,level,sfx,language}=useGame();useEffect(()=>{document.documentElement.lang=language},[language]);useEffect(()=>{const enterFullscreen=()=>{AudioManager.unlock();if(!window.matchMedia('(pointer: coarse)').matches||window.matchMedia('(display-mode: standalone)').matches||document.fullscreenElement)return;void document.documentElement.requestFullscreen?.({navigationUI:'hide'}).catch(()=>{})};document.addEventListener('pointerup',enterFullscreen,{once:true});document.addEventListener('touchstart',enterFullscreen,{once:true,passive:true});return()=>{document.removeEventListener('pointerup',enterFullscreen);document.removeEventListener('touchstart',enterFullscreen)}},[]);useEffect(()=>{const unlock=()=>AudioManager.unlock();const resumeContext=()=>{if(document.visibilityState==='hidden'){AudioManager.stop('music');AudioManager.stop('sfx');return}unlock();if(screen==='battle'){if(music)AudioManager.play(selectedBattleLevel(level)%10===0?'boss_theme':'battle_theme','music')}else if(screen!=='result'&&screen!=='defeat'&&music)AudioManager.play('lobby_theme','music')};const handleUiClick=(event:MouseEvent)=>{unlock();const target=event.target as HTMLElement|null;if(target?.closest('button,[role="button"],input,select'))AudioManager.play('ui_click','ui');};document.addEventListener('pointerdown',unlock,{passive:true});document.addEventListener('touchstart',unlock,{passive:true});document.addEventListener('click',handleUiClick,true);document.addEventListener('visibilitychange',resumeContext);window.addEventListener('pageshow',resumeContext);return()=>{document.removeEventListener('pointerdown',unlock);document.removeEventListener('touchstart',unlock);document.removeEventListener('click',handleUiClick,true);document.removeEventListener('visibilitychange',resumeContext);window.removeEventListener('pageshow',resumeContext)}},[screen,music,level]);useEffect(()=>{if(screen==='battle'){AudioManager.stop('sfx');const battleLevel=selectedBattleLevel(level);if(music)AudioManager.play(battleLevel%10===0?'boss_theme':'battle_theme','music');else AudioManager.stop('music');}else if(screen==='result'){AudioManager.stop('music');AudioManager.stop('sfx');if(sfx)AudioManager.play('victory','sfx');}else if(screen==='defeat'){AudioManager.stop('music');AudioManager.stop('sfx');if(sfx)AudioManager.play('defeat','sfx');}else if(music)AudioManager.play('lobby_theme','music');else AudioManager.stop('music');},[screen,music,level,sfx]);let content=screen==='lobby'?<Lobby/>:screen==='map'?<MapScreen/>:screen==='loadout'?<Loadout/>:screen==='tutorial'?<Tutorial/>:screen==='loading'?<Loading/>:screen==='battle'?<BattleV2/>:screen==='result'?<Result/>:screen==='defeat'?<Defeat/>:screen==='units'?<Collection kind="units"/>:screen==='weapons'?<Collection kind="weapons"/>:screen==='shop'?<Shop/>:screen==='stats'?<Stats/>:screen==='daily'?<Daily/>:screen==='missions'?<Missions/>:screen==='pass'?<Pass/>:screen==='settings'?<Settings/>:screen==='terms'?<TermsOfUse/>:screen==='support'?<Support/>:screen==='privacy'?<PrivacyPolicy/>:screen==='skins'?<Skins/>:screen==='achievements'?<Achievements/>:screen==='crystal'?<CrystalChallenge/>:<Profile/>;const immersive=screen==='battle'||screen==='result'||screen==='defeat'||screen==='loading'||screen==='tutorial';return <main className={'app screen-'+screen+(screen==='battle'?' battle-screen':'')}><div className="screen-frame">{content}</div>{toast&&<div className="toast">{toast}</div>}{!immersive&&<DebugPanel/>}{!immersive&&<BottomNav/>}<StarterOfferOverlay/></main>}
if(import.meta.env.PROD&&'serviceWorker' in navigator&&!Capacitor.isNativePlatform())window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').then(registration=>registration.update()));
function AnalyticsRuntime(){
  const screen=useGame(state=>state.screen),level=useGame(state=>state.level);
  const [debugEnabled,setDebugEnabled]=useState(false);
  useEffect(()=>{void AnalyticsService.initialize().finally(()=>setDebugEnabled(AnalyticsService.isDebugBuild()))},[]);
  useEffect(()=>{const state=useGame.getState(),world=getWorldByLevel(state.level);AnalyticsService.trackScreen(screen);AnalyticsService.updatePlayerProperties({playerLevel:state.level,currentWorld:world.key,highestLevelReached:state.level,payerStatus:localStorage.getItem('starterPackPurchased')==='true'?'payer':'non_payer'})},[screen,level]);
  useEffect(()=>{const trackLobbyPlay=(event:MouseEvent)=>{const button=(event.target as HTMLElement|null)?.closest('button');if(button?.textContent?.trim()!=='PLAY')return;const state=useGame.getState();AnalyticsService.trackPlayClicked(state.level,getWorldByLevel(state.level).key)};document.addEventListener('click',trackLobbyPlay,true);return()=>document.removeEventListener('click',trackLobbyPlay,true)},[]);
  useEffect(()=>{if(!debugEnabled)return;const target=window as typeof window&{moboFirebaseDebug?:{sendAnalyticsTest:()=>Promise<void>;testCrash:()=>Promise<void>}};target.moboFirebaseDebug={sendAnalyticsTest:()=>AnalyticsService.sendDebugTest(),testCrash:()=>AnalyticsService.triggerTestCrash()};return()=>{delete target.moboFirebaseDebug}},[debugEnabled]);
  return null;
}
createRoot(document.getElementById('root')!).render(<React.StrictMode><AppErrorBoundary><AnalyticsRuntime/><App/></AppErrorBoundary></React.StrictMode>);
